B.a61=new A.f(1647,"adult_duration",u.A6)
B.a6p=new A.f(1672,"caution","RED FLAG - Pregnant women exposed to suspected rubella require immediate serologic IgG testing; infection before 18 weeks gestation carries high risk of fetal infection/congenital malformation and may warrant discussion of pregnancy termination.")
B.a6q=new A.f(1688,"adult_dose",u.Dz)
